def migra_dati(apps, schema_editor):
    """Porta i dati esistenti sulla nuova struttura prima di rimuovere i vecchi campi:
    - il fornitore unico del corso diventa un'offerta, limitata ai negozi_abilitati
      del fornitore se valorizzati (altrimenti valida per tutti i negozi);
    - il registro compilato unico della sessione diventa il primo documento di chiusura."""
    EHSCorso = apps.get_model('ehs', 'EHSCorso')
    EHSOffertaCorso = apps.get_model('ehs', 'EHSOffertaCorso')
    EHSSessione = apps.get_model('ehs', 'EHSSessione')
    EHSSessioneDocumento = apps.get_model('ehs', 'EHSSessioneDocumento')

    for corso in EHSCorso.objects.exclude(fornitore__isnull=True).select_related('fornitore'):
        negozi = list(corso.fornitore.negozi_abilitati.all())
        offerta = EHSOffertaCorso.objects.create(
            corso=corso, fornitore=corso.fornitore, tutti_negozi=not negozi,
        )
        if negozi:
            offerta.negozi.set(negozi)

    for sessione in EHSSessione.objects.exclude(registro_compilato_file='').exclude(registro_compilato_file__isnull=True):
        doc = EHSSessioneDocumento.objects.create(
            sessione=sessione,
            file=sessione.registro_compilato_file.name,
            nome_originale=sessione.registro_compilato_file.name.rsplit('/', 1)[-1],
            caricato_da=sessione.chiusa_da,
        )
        if sessione.data_chiusura:
            EHSSessioneDocumento.objects.filter(pk=doc.pk).update(caricato_il=sessione.data_chiusura)


